def solve(nums, target):
    low = 0
    high = len(nums) - 1
    first = -1
    last = -1

    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            first = mid
            high = mid - 1  # Continue searching on the left for the first occurrence
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    if first == -1:
        return [-1, -1]

    low = 0
    high = len(nums) - 1

    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            last = mid
            low = mid + 1  # Continue searching on the right for the last occurrence
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return [first, last]
