def solve(nums, target):
    left = 0
    right = len(nums) - 1
    result = [-1, -1]

    if not nums:
        return result

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            result[0] = mid
            right = mid - 1  # Continue searching on the left side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result
```

