    Given a list of integers nums and a target integer, return a list [i, j] of two indices with i < j such that nums[i] + nums[j] == target.
    """
    seen = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], index]
        seen[num] = index
